  'Use = or := to define, e.g. a = 5 or f(x) := x^2 + 1. Use e for Euler’s number and i for √−1.': '= または := で定義します（例：a = 5、f(x) := x^2 + 1）。e はネイピア数、i は √−1 です。',
  'Use = to define, e.g. a = 5 or f(x) = x^2 + 1. Use exp(x) for eˣ, i for √−1, and float(…) for decimals.': '= で定義します（例：a = 5、f(x) = x^2 + 1）。eˣ は exp(x)、i は √−1、小数は float(…) で求めます。',
