  'Choosing an algorithm': 'アルゴリズムの選び方',
  'A first pick for common tabular problems. Start simple, get a baseline, then move to boosting.': '一般的な表形式データ問題の最初の候補です。まずはシンプルに始めてベースラインを作り、その後ブースティングへ進みます。',
  'First choice by problem': '問題別の第一候補',
  'Problem': '問題',
  'Baseline': 'ベースライン',
