  'The usual workflow for XGBoost, LightGBM, and CatBoost: let early stopping pick the number of trees, tune the rest.': 'XGBoost・LightGBM・CatBoost の定番ワークフロー：木の本数は早期終了に決めさせ、残りをチューニングします。',
