  'Split train/valid/test': 'train/valid/test に分割',
  'Encode categoricals': 'カテゴリ変数のエンコード',
  'Fit with early stopping': '早期終了付きで学習',
  'Tune (Optuna / random)': 'チューニング（Optuna／ランダム）',
  'Refit with best rounds': '最適ラウンド数で再学習',
