  'GRU / LSTM or 1D CNN': 'GRU / LSTM または 1D CNN',
  'Transformer encoder, temporal conv nets.': 'Transformer エンコーダー、時間畳み込みネットワーク。',
  '(N, L) token ids': '(N, L) のトークン ID',
  'Pretrained transformer (Hugging Face)': '学習済み Transformer（Hugging Face）',
  'Embedding + LSTM for small, simple tasks.': '小規模で単純なタスクには Embedding + LSTM。',
