  'Tensor basics': 'テンソルの基本',
  'Create, reshape, and move tensors.': 'テンソルの作成、形状変更、デバイス間の移動。',
  'Shape operations': '形状の操作',
  'Operation': '操作',
  '`view` needs contiguous memory; `reshape` copies when needed.': '`view` は連続したメモリが必要で、`reshape` は必要に応じてコピーします。',
  'Keep batch dim, flatten the rest.': 'バッチ次元を残し、残りを平坦化します。',
  'NCHW → NHWC. Follow with `.contiguous()` before `view`.': 'NCHW → NHWC。`view` の前に `.contiguous()` を呼びます。',
  'Swap two dims: (N, L, C) ↔ (N, C, L) for Conv1d.': '2 つの次元を入れ替えます：Conv1d 用に (N, L, C) ↔ (N, C, L)。',
