  'nn.Module & containers': 'nn.Module とコンテナー',
  'Every model is an `nn.Module`: define layers in `__init__`, the computation in `forward`.': 'すべてのモデルは `nn.Module` です。レイヤーは `__init__` で定義し、計算は `forward` に書きます。',
