  '`groups=in_channels` = depthwise conv (MobileNet).': '`groups=in_channels` はデプスワイズ畳み込み（MobileNet）。',
  'Conv block': '畳み込みブロック',
  'Upsampling for decoders, U-Nets, and GANs.': 'デコーダー、U-Net、GAN 向けのアップサンプリング。',
  '`Upsample` + `Conv2d` avoids checkerboard artifacts that ConvTranspose can create.': '`Upsample` + `Conv2d` なら、ConvTranspose で生じうるチェッカーボードアーティファクトを避けられます。',
  '`kernel_size=2, stride=2` doubles size cleanly.': '`kernel_size=2, stride=2` ならサイズがきれいに 2 倍になります。',
  'Fix off-by-one output sizes.': '出力サイズの 1 ずれを修正します。',
  'Usually False with bilinear.': 'bilinear では通常 False にします。',
  'Pooling layers': 'プーリング層',
  'Downsample feature maps. Keras: `MaxPooling2D`, `GlobalAveragePooling2D`.': '特徴マップをダウンサンプルします。Keras：`MaxPooling2D`、`GlobalAveragePooling2D`。',
  '2 halves H and W.': '2 で H と W が半分になります。',
  'None (= kernel_size)': 'None（= kernel_size）',
  'Round output size up.': '出力サイズを切り上げます。',
  '`1` = global average pooling; works for any input size.': '`1` = グローバル平均プーリング。任意の入力サイズで動作します。',
  'BatchNorm / LayerNorm / GroupNorm': 'BatchNorm / LayerNorm / GroupNorm',
  'Normalize activations to stabilize and speed up training.': '活性化を正規化して、学習を安定化・高速化します。',
  'BatchNorm for CNNs with batch ≥ 16; LayerNorm for transformers and RNNs; GroupNorm for CNNs with small batches.': 'バッチ ≥ 16 の CNN には BatchNorm、Transformer と RNN には LayerNorm、バッチが小さい CNN には GroupNorm。',
  'BatchNorm behaves differently in train and eval mode: call `model.eval()` before validation.': 'BatchNorm は train と eval で挙動が異なります。検証の前に `model.eval()` を呼んでください。',
  'Use `nn.RMSNorm(d)` (PyTorch ≥ 2.4) for LLaMA-style blocks.': 'LLaMA 型のブロックには `nn.RMSNorm(d)`（PyTorch ≥ 2.4）を使います。',
  'Channels C (BatchNorm2d) or features (BatchNorm1d).': 'チャンネル数 C（BatchNorm2d）または特徴量数（BatchNorm1d）。',
  'Running-stat update rate. Keras uses momentum=0.99 with the opposite meaning.': '移動統計量の更新率。Keras の momentum=0.99 は意味が逆です。',
  'Learnable scale and shift.': '学習可能なスケールとシフト。',
  'Trailing dims to normalize, usually `d_model`.': '正規化する末尾の次元。通常は `d_model`。',
  'Randomly zero activations during training. Disabled by `model.eval()`.': '学習中に活性化をランダムに 0 にします。`model.eval()` で無効になります。',
  '`nn.Dropout2d` drops whole channels for conv feature maps.': '`nn.Dropout2d` は畳み込み特徴マップのチャンネル全体をドロップします。',
  '0.1–0.3 for conv/transformers, 0.3–0.5 for dense layers.': '畳み込み／Transformer では 0.1〜0.3、全結合層では 0.3〜0.5。',
  'Lookup table from integer ids to dense vectors. Keras: `layers.Embedding(input_dim, output_dim)`.': '整数 ID から密ベクトルへのルックアップテーブル。Keras：`layers.Embedding(input_dim, output_dim)`。',
  'Tokens, categorical features, user/item ids.': 'トークン、カテゴリ特徴量、ユーザー／アイテム ID。',
  'Vocabulary size (max id + 1).': '語彙サイズ（最大 ID + 1）。',
  'Rule of thumb for categoricals: min(50, (cardinality + 1) // 2).': 'カテゴリ変数の目安：min(50, (カーディナリティ + 1) // 2)。',
  'This id stays a zero vector and gets no gradient.': 'この ID はゼロベクトルのままで、勾配を受け取りません。',
  'Renormalize vectors above this norm.': 'このノルムを超えるベクトルを再正規化します。',
  'Sparse gradients for huge vocabularies (use SparseAdam).': '巨大な語彙向けの疎な勾配です（SparseAdam を使います）。',
  'Recurrent layers. Return `(output, h_n)` (GRU/RNN) or `(output, (h_n, c_n))` (LSTM). Keras: `layers.LSTM(units, return_sequences=...)`.': '再帰レイヤー。`(output, h_n)`（GRU/RNN）または `(output, (h_n, c_n))`（LSTM）を返します。Keras：`layers.LSTM(units, return_sequences=...)`。',
  'Features per time step.': 'タイムステップごとの特徴量数。',
  '2–3 stacked layers.': '2〜3 層を積み重ねます。',
  'Set True to use (N, L, H_in). Default is (L, N, H_in)!': 'True にすると (N, L, H_in) を使います。既定は (L, N, H_in) です。',
  'Between stacked layers only (needs num_layers > 1).': '積み重ねた層の間にのみ適用されます（num_layers > 1 が必要）。',
  'Doubles output features. Not for forecasting/causal tasks.': '出力特徴量が 2 倍になります。予測／因果的なタスクには使えません。',
  'Project hidden state to a smaller size.': '隠れ状態をより小さいサイズに射影します。',
  'Sequence classifier': '系列分類器',
  'Attention(Q, K, V) = softmax(QKᵀ / √d) V. Keras: `layers.MultiHeadAttention(num_heads, key_dim)`.': 'Attention(Q, K, V) = softmax(QKᵀ / √d) V。Keras：`layers.MultiHeadAttention(num_heads, key_dim)`。',
  'Must be divisible by num_heads.': 'num_heads で割り切れる必要があります。',
  '4–16; head dim of 64 is typical.': '4〜16。ヘッドの次元は 64 が一般的です。',
  'On attention weights.': 'アテンション重みに適用されます。',
  'Set True for (N, L, E).': '(N, L, E) の入力には True にします。',
  'None (= embed_dim)': 'None（= embed_dim）',
  'For cross-attention with different key/value sizes.': 'キーと値のサイズが異なるクロスアテンション用です。',
  'True marks padding positions to ignore.': 'True はパディング位置を無視する印です。',
  'bool or float (L, S)': 'bool または float (L, S)',
  'True = not allowed to attend.': 'True = 注目が許可されない位置。',
  'is_causal (SDPA / forward)': 'is_causal（SDPA / forward）',
  'Autoregressive mask without building it yourself.': '自己回帰マスクを自分で作らずに使えます。',
  'Set False for the fast path.': '高速パスを使うには False にします。',
  'Fused attention (Flash / memory-efficient kernels)': '融合アテンション（Flash／メモリ効率の良いカーネル）',
  'Self-attention + feed-forward block with residuals and LayerNorm.': '残差接続と LayerNorm を伴う、セルフアテンション + フィードフォワードのブロック。',
  'Embedding size.': '埋め込みサイズ。',
  'Usually 4 × d_model.': '通常は 4 × d_model です。',
