  'Set True.': 'True にします。',
  'True = pre-LN; trains more stably for deep stacks.': 'True = pre-LN。深く積む場合に学習がより安定します。',
  'Transformer classifier': 'Transformer 分類器',
  'Encoder–decoder transformer and the decoder layer with causal masking.': 'エンコーダー・デコーダー型 Transformer と、因果マスク付きのデコーダーレイヤー。',
  'Sequence-to-sequence (translation, summarization) or decoder-only language models. For text, a pretrained Hugging Face model is usually better than training from scratch.': '系列変換（翻訳、要約）やデコーダーのみの言語モデル向け。テキストなら、ゼロから学習するより Hugging Face の学習済みモデルのほうが通常は良好です。',
  'Must be divisible by nhead.': 'nhead で割り切れる必要があります。',
  'Set True for (N, S, E) inputs.': '(N, S, E) の入力には True にします。',
  'True (pre-norm) trains more stably for deep stacks.': 'True（pre-norm）は深く積む場合に学習がより安定します。',
  '(T, T) bool / float mask': '(T, T) の bool / float マスク',
  '`nn.Transformer.generate_square_subsequent_mask(T)` blocks attention to future tokens.': '`nn.Transformer.generate_square_subsequent_mask(T)` は未来のトークンへのアテンションを遮断します。',
