  '`CTC` via `keras.ops.ctc_loss`': '`keras.ops.ctc_loss` による `CTC`',
  'LogSoftmax + NLLLoss in one. Input: raw logits (N, C); target: class ids (N,) or class probabilities (N, C).': 'LogSoftmax + NLLLoss を一つにしたもの。入力：生のロジット (N, C)、ターゲット：クラス ID (N,) またはクラス確率 (N, C)。',
