  'Target value to skip (padding tokens).': 'スキップするターゲット値（パディングトークン）。',
  '`none` for per-sample losses.': 'サンプルごとの損失には `none`。',
  '0.1 reduces over-confidence.': '0.1 で過信を抑えられます。',
  'Sigmoid + binary cross entropy, numerically stable. For binary and multi-label targets.': 'シグモイド + 二値交差エントロピーを数値的に安定して計算します。二値・多ラベルのターゲット向けです。',
  'Targets must be float: `y.float()`.': 'ターゲットは float にする必要があります：`y.float()`。',
  'Predicted probability: `torch.sigmoid(logits)`.': '予測確率：`torch.sigmoid(logits)`。',
  'Imbalance: ≈ negatives / positives per label.': '不均衡の場合：ラベルごとの 負例数 ÷ 正例数 が目安です。',
  'Per-element rescaling.': '要素ごとの再スケーリング。',
  'Regression losses.': '回帰用の損失関数。',
  'MSE for Gaussian noise; L1 for robustness to outliers; Huber/SmoothL1 for both (bounding boxes, RL).': 'ガウスノイズには MSE、外れ値への頑健性には L1、両立には Huber/SmoothL1（バウンディングボックス、強化学習）。',
  'Match shapes: `pred.squeeze(-1)` vs target (N,) — broadcasting (N,1) vs (N,) silently gives the wrong loss.': '形状を合わせてください：`pred.squeeze(-1)` とターゲット (N,)。(N,1) と (N,) のブロードキャストは黙って誤った損失を返します。',
  'Errors above delta are treated linearly.': 'delta を超える誤差は線形に扱われます。',
