  'Focal loss for heavy class imbalance or dense detection; Dice for segmentation with small foreground; contrastive losses for embeddings.': '強いクラス不均衡や密な検出には Focal loss、前景が小さいセグメンテーションには Dice、埋め込みには対照損失。',
  'Other losses': 'その他の損失関数',
