  'Optimizers': 'オプティマイザー',
  'AdamW is the safe default; SGD with momentum often generalizes best for CNNs with a good schedule.': 'AdamW が安全な既定です。良いスケジュールと組み合わせれば、CNN ではモーメンタム付き SGD の汎化が最良になることが多いです。',
  '1e-3 from scratch; 1e-5–5e-5 to fine-tune transformers; 1e-4 to fine-tune CNNs.': 'ゼロから学習なら 1e-3、Transformer のファインチューニングなら 1e-5〜5e-5、CNN のファインチューニングなら 1e-4。',
  '(0.9, 0.95) for large transformers.': '大規模な Transformer には (0.9, 0.95)。',
  '0.01–0.1. Exclude biases and norm weights.': '0.01〜0.1。バイアスと正規化層の重みは除外します。',
